// Lane Init: the Supersoniq lane of Enrich Contacts. One run per launch over the WHOLE company
// list; the lane worries about itself: it walks the list in chunks of 500 companies (the
// size this vendor's API and pacing want), asks the vendor per chunk, and hands each chunk's people
// to the writer helper. The Rootflow only orchestrates. The input item is the Rootflow's contract:
// { base, peopleTableId, companiesTableId, peopleFields, contactSourceMulti, dncDomains,
//   companies:[{recordId, domain, company, band, cap, floor}], parentExecId, clientRecId }.
const inp=$input.first().json||{};
const who='Enrich Contacts Supersoniq lane';
if(!/^app[A-Za-z0-9]{14}$/.test(String(inp.base||''))) throw new Error(who+' was called without a valid base.');
if(!inp.peopleTableId) throw new Error(who+' was called without peopleTableId.');
const companies=(Array.isArray(inp.companies)?inp.companies:[]).filter(c=>c&&c.domain);
const sd=$getWorkflowStaticData('global');
sd.lane={ execId:String($execution.id), startedAt:new Date().toISOString(), chunks:0, called:0, returned:0, kept:0, credits:0, errors:0, firstError:'', skipped:'', built:0, updated:0, heldUnchanged:0, dupes:0, noKey:0, fenced:0, emailsAppended:0, dnc:0, written:0, updatedWritten:0, writeErrors:0, writeReasons:[], coveredDomains:{}, singleSelectSource:false, companiesIn:companies.length };
const CHUNK=500;
const out=[];
for(let i=0;i<companies.length;i+=CHUNK){ out.push({ json:{ idx:out.length+1, count:Math.ceil(companies.length/CHUNK), companies:companies.slice(i,i+CHUNK) } }); }
if(!out.length) return [{ json:{ _empty:true, idx:0, count:0, companies:[] } }];
return out;

// SQ Requests: the Supersoniq provider of Enrich Contacts. Supersoniq is the one metered source
// (one credit per delivered contact, 90k a month), so it gets its own rule (ruled 2026-09-09): a
// HARD cap of 10 people per company whatever the band, and seniors only (Director and up in its
// vocabulary: Director, Head, VP, EVP / SVP, President, C-Suite, Owner, Founder, Partner,
// Board / Chair). One POST companies/enrich per 1,000 domains, tier full so the email rides.
const inp=$input.first().json||{};
const companies=(Array.isArray(inp.companies)?inp.companies:[]).filter(c=>c&&c.domain);
const CAP=10;
const SENIORS=['Director','Head','VP','EVP / SVP','President','C-Suite','Owner','Founder','Partner','Board / Chair'];
const domains=companies.map(c=>String(c.domain).toLowerCase());
const out=[];
for(let i=0;i<domains.length;i+=1000){
  const part=domains.slice(i,i+1000);
  out.push({ json:{ body:{ companies:part.map(d=>({ domain:d })), filters:{ seniority:SENIORS }, per_company_limit:CAP, tier:'full' }, domains:part, cap:CAP } });
}
if(!out.length) return [{ json:{ _none:true } }];
return out;

// SQ Parse: companies/enrich answers (aligned to SQ Requests by index; the node never errors, a
// failure is the body) -> people per domain in the shared provider contract (see GL Parse). A
// contact at a domain we did not send is dropped; an email whose domain is neither the company
// domain nor a subdomain of it is blanked, the person kept. Out of credits is a skip, never an
// error: the caller carries on with the other providers. Never throws.
// n8n hands a node failure over as {error}: a plain string ("Credentials not found") or an object with message and description. Read both shapes.
const errMsg=(e)=>{ if(!e) return 'call failed'; if(typeof e==='string') return e; return String((e.message||'')+' '+(e.description||'')).trim()||'call failed'; };
const inp=$('SQ Requests').first().json||{};
const st={ called:0, returned:0, kept:0, credits:0, errors:0, firstError:'', failReasons:[], dropped:0, emailBlanked:0 };
const people={};
if(inp._none){ return [{ json:{ provider:'Supersoniq', status:'skipped', reason:'nothing to ask', stats:st, people:{} } }]; }
let reqs=[]; try{ reqs=$('SQ Requests').all().map(i=>i.json||{}); }catch(e){}
let items=[]; try{ items=$('SQ Enrich').all(); }catch(e){}
const emailDomainOk=(email,domain)=>{ const at=String(email||'').lastIndexOf('@'); if(at<0) return false; const ed=String(email).slice(at+1).toLowerCase().trim(); return ed===domain||ed.endsWith('.'+domain); };
let noKey=false, noCredits=false;
items.forEach((it,i)=>{
  const req=reqs[i]; if(!req) return;
  st.called++;
  const resp=it.json||{};
  if(resp.error&&resp.results===undefined&&(typeof resp.error==='object'||typeof resp.error==='string')){
    const msg=errMsg(resp.error);
    if(/credential/i.test(msg)){ noKey=true; return; }
    st.errors++; const r='Supersoniq: '+msg.slice(0,160); if(!st.firstError) st.firstError=r; st.failReasons.push(r); return;
  }
  if(!Array.isArray(resp.results)){
    const txt=JSON.stringify(resp).slice(0,200);
    if(/credit|balance|insufficient/i.test(txt)){ noCredits=true; const r='Supersoniq: '+txt; if(!st.firstError) st.firstError=r; st.failReasons.push(r); return; }
    if(/authentication|unauthori|api key/i.test(txt)){ noKey=true; return; }
    st.errors++; const r='Supersoniq: '+txt; if(!st.firstError) st.firstError=r; st.failReasons.push(r); return;
  }
  const cr=resp.credits_used!=null?resp.credits_used:(resp.credits!=null?resp.credits:((resp.usage&&resp.usage.credits_used)||0)); st.credits+=Number(cr)||0;
  const sent=new Set(req.domains);
  for(const r of resp.results){
    const contacts=Array.isArray(r.contacts)?r.contacts:[];
    for(const ct of contacts){
      st.returned++;
      const domain=String(ct.company_domain||'').trim().toLowerCase();
      if(!domain||!sent.has(domain)){ st.dropped++; continue; }
      const list=people[domain]||(people[domain]=[]);
      if(list.length>=req.cap) continue;
      const full=((String(ct.first_name||'')+' '+String(ct.last_name||'')).trim())||String(ct.full_name||'');
      if(!full) continue;
      let email=String(ct.email||'').trim().toLowerCase();
      if(email&&!emailDomainOk(email,domain)){ email=''; st.emailBlanked++; }
      list.push({ source:'Supersoniq', sourceId:String(ct.contact_id||ct.id||''), name:full, title:String(ct.job_title||'').trim(), seniority:String(ct.seniority||''), department:String(ct.function||''), email:email, linkedin:String(ct.linkedin_url||ct.linkedin||'').trim(), phone:'' });
      st.kept++;
    }
  }
});
let status='ok', reason='';
if(noKey&&!st.kept&&!st.errors){ status='skipped'; reason='no credential on the Supersoniq node'; }
else if(noCredits&&!st.kept){ status='skipped'; reason='out of credits'; }
else if(st.errors&&items.length&&st.errors>=items.length&&!st.kept){ status='error'; reason=st.firstError; }
return [{ json:{ provider:'Supersoniq', status, reason, stats:st, people } }];

// Writer Input: this chunk's people (from SQ Parse) plus the writer's contract, one item for the
// writer helper. An empty answer still goes through the writer (it costs one held read and returns
// zero), so the lane's counters stay honest and simple.
const ctx=$('Enrich Trigger').first().json||{};
const chunk=$('Chunk Loop').first().json||{};
let parsed={}; try{ parsed=$('SQ Parse').first().json||{}; }catch(e){}
return [{ json:{ base:ctx.base, peopleTableId:ctx.peopleTableId, peopleFields:ctx.peopleFields||[], contactSourceMulti:ctx.contactSourceMulti===true, dncDomains:ctx.dncDomains||[], provider:'Supersoniq', companies:chunk.companies||[], people:(parsed.people&&typeof parsed.people==='object')?parsed.people:{} } }];

// Lane Tick: adds this chunk's vendor counters (SQ Parse) and writer counters (Call Writer) to the
// lane's running totals in this execution's static data (one execution, so the accumulator holds),
// then emits one unconditional tick so the loop never depends on the payload of the work.
const sd=$getWorkflowStaticData('global'); const a=sd.lane;
const n=(v)=>Number(v)||0;
let p={}; try{ p=$('SQ Parse').first().json||{}; }catch(e){}
const s=p.stats||{};
a.chunks++; a.called+=n(s.called); a.returned+=n(s.returned); a.kept+=n(s.kept); a.credits+=n(s.credits); a.errors+=n(s.errors);
if(!a.firstError&&s.firstError) a.firstError=String(s.firstError).slice(0,200);
if(p.status==='skipped'&&p.reason&&p.reason!=='nothing to ask') a.skipped=String(p.reason);
if(p.status==='error'&&!a.firstError) a.firstError=String(p.reason||'').slice(0,200);
let w={}; try{ w=$('Call Writer').first().json||{}; }catch(e){}
if(w.error&&w.written===undefined){ a.writeErrors+=1; if(a.writeReasons.length<5) a.writeReasons.push('writer crashed: '+String((w.error&&w.error.message)||w.error).slice(0,160)); }
else { for(const k of ['built','updated','heldUnchanged','dupes','noKey','fenced','emailsAppended','dnc','written','updatedWritten','writeErrors']) a[k]+=n(w[k]); if(w.singleSelectSource) a.singleSelectSource=true; for(const r of (w.writeReasons||[])){ if(a.writeReasons.length<5&&a.writeReasons.indexOf(r)<0) a.writeReasons.push(r); } for(const d of (w.coveredDomains||[])) a.coveredDomains[d]=1; }
return [{ json:{ tick:true, chunk:a.chunks } }];

// Lane Log: the lane's own Hub row, keyed "<parent execution>-supersoniq", Automation
// "Enrich Contacts Supersoniq", Client attached. Status computed: a skipped lane (no credential,
// out of credits, nothing to ask) is Succeeded with a Skipped line; vendor errors and refused
// writes count as errors; Failed only when every call failed and nothing was written.
const ctx=$('Enrich Trigger').first().json||{};
const a=$getWorkflowStaticData('global').lane||{};
const n=(v)=>Number(v)||0;
const covered=Object.keys(a.coveredDomains||{}).length;
const failed=n(a.errors)+n(a.writeErrors);
let dur=0; try{ dur=Math.max(0,Math.round(($now.toMillis()-new Date(a.startedAt).getTime())/1000)); }catch(e){}
const allFailed=n(a.called)>0&&n(a.errors)>=n(a.called)&&!n(a.written);
const lines=[
  '**Supersoniq: '+n(a.companiesIn)+' companies asked in '+n(a.chunks)+' chunk'+(n(a.chunks)===1?'':'s')+', '+n(a.returned)+' people returned, '+n(a.built)+' new, '+n(a.updated)+' held filled, '+n(a.written)+' rows written**',
  '', '**Parent run:** '+(ctx.parentExecId||'?')+' (this row is the Supersoniq lane of it)',
  '', '- **Vendor:** called '+n(a.called)+', returned '+n(a.returned)+', kept '+n(a.kept)+(n(a.credits)?', credits '+(Math.round(n(a.credits)*100)/100):'')+(n(a.errors)?', errors '+n(a.errors)+(a.firstError?' ('+a.firstError+')':''):''),
  '- **Merge:** '+n(a.built)+' new rows; '+n(a.updated)+' held rows filled ('+n(a.emailsAppended)+' emails appended); '+n(a.heldUnchanged)+' held unchanged; '+n(a.dupes)+' same-person merges; '+n(a.noKey)+' without a usable first name; '+n(a.fenced)+' LinkedIn URLs rejected by the name fence; '+n(a.dnc)+' on the DNC list',
  '- **Written (confirmed by Airtable):** '+n(a.written)+' ('+n(a.updatedWritten)+' updates of held rows)'+(n(a.writeErrors)?', '+n(a.writeErrors)+' refused':''),
  '- **Companies with at least one person after this lane:** '+covered
];
if(a.singleSelectSource) lines.push('- **Contact Source is a single select on this base:** only the first source per person was recorded');
if(a.skipped) lines.push('', '**Skipped ('+a.skipped+')**');
if((a.writeReasons||[]).length){ lines.push('', '**Write failures**'); for(const r of a.writeReasons) lines.push('- '+r); }
const log={ 'Execution ID':(ctx.parentExecId||String($execution.id))+'-supersoniq', 'Automation':'Enrich Contacts Supersoniq', 'Status':allFailed?'Failed':(failed?'Succeeded with errors':'Succeeded'), 'Trigger':'event', 'Errors':failed, 'Run at':a.startedAt, 'Target':'People ('+(ctx.peopleTableId||'')+')', 'Records In':n(a.companiesIn), 'Records Out':n(a.written), 'Duration s':dur, 'Description':lines.join('\n'), 'Tally':JSON.stringify(Object.assign({}, a, { coveredDomains:covered })), 'Execution Link':'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id };
if(ctx.clientRecId) log['Client']=[ctx.clientRecId];
return [{ json:log }];

// Lane Response: the last node, what the Rootflow receives from this lane: counters only.
const a=$getWorkflowStaticData('global').lane||{};
const covered=Object.keys(a.coveredDomains||{});
return [{ json:{ provider:'Supersoniq', status:a.skipped?'skipped':((a.called&&a.errors>=a.called&&!a.written)?'error':'ok'), reason:a.skipped||a.firstError||'', chunks:a.chunks, called:a.called, returned:a.returned, kept:a.kept, credits:a.credits, errors:a.errors, built:a.built, updated:a.updated, dupes:a.dupes, fenced:a.fenced, emailsAppended:a.emailsAppended, dnc:a.dnc, written:a.written, writeErrors:a.writeErrors, singleSelectSource:!!a.singleSelectSource, coveredDomains:covered } }];
